// Deterministic Latin -> Elder Futhark transliteration for normalized Old Norse spelling.
// Used for lesson words so runes are generated by this table, never by the AI (which
// invents wrong runes). Elder Futhark predates Old Norse, so this is the conventional
// letter-for-letter rendering, not a historical inscription: vowel length is dropped,
// doubled letters collapse (runic writing didn't double), ø/ö/ǫ -> ᛟ, æ -> ᛖ, ð -> ᛞ.

const MAP = {
  a: "ᚨ", b: "ᛒ", c: "ᚲ", d: "ᛞ", e: "ᛖ", f: "ᚠ", g: "ᚷ", h: "ᚺ", i: "ᛁ", j: "ᛃ",
  k: "ᚲ", l: "ᛚ", m: "ᛗ", n: "ᚾ", o: "ᛟ", p: "ᛈ", q: "ᚲᚹ", r: "ᚱ", s: "ᛊ", t: "ᛏ",
  u: "ᚢ", v: "ᚹ", w: "ᚹ", x: "ᚲᛊ", y: "ᛁ", z: "ᛉ",
  "þ": "ᚦ", "ð": "ᛞ", "æ": "ᛖ", "ø": "ᛟ", "œ": "ᛟ",
};
export const RUNE_WORD_DIVIDER = "᛫"; // U+16EB

export function toRunes(text) {
  const t = (text || "").toLowerCase().replace(/th/g, "þ").replace(/ng/g, "\u0001");
  let out = "";
  let prev = "";
  // NFD splits accented vowels (á, ö, ǫ) into base + combining mark; marks are dropped.
  for (const ch of t.normalize("NFD")) {
    if (/[̀-ͯ]/.test(ch)) continue;
    let r;
    if (ch === "\u0001") r = "ᛜ";
    else if (MAP[ch]) r = MAP[ch];
    else if (/\s/.test(ch) || ch === "-") r = out && !out.endsWith(RUNE_WORD_DIVIDER) ? RUNE_WORD_DIVIDER : "";
    else r = "";
    if (r && r === prev && r !== RUNE_WORD_DIVIDER) continue; // collapse doubled letters
    out += r;
    if (r) prev = r;
  }
  return out.replace(new RegExp(RUNE_WORD_DIVIDER + "+$"), "");
}
